css:
/* a comment with .cmd-dot[data-state="ghost"] in it — stripped before the scan */
.cmd-dot[data-state="ok"] { background: var(--ok); }
.cmd-dot[data-state="fail"], .cmd-dot[data-state="unknown"] { background: var(--fail); }
.cmd-dot.is-unknown { opacity: .5; }
.led-dot[data-live="on"] { background: var(--ok); }
.plug-dot[error] { box-shadow: inset 0 0 0 1px var(--fail); }
.update-state.is-error { color: var(--fail); }
.btn-primary:hover { transform: translateY(1px); }
